OUTPUT_PATH = "data_raw/normalizer_predictions.jsonl"


def main():
    assert len(MANUAL_PREDICTIONS) == 78, f"Expected 78 rows, got {len(MANUAL_PREDICTIONS)}"

    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)

    with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
        for record in MANUAL_PREDICTIONS:
            f.write(json.dumps(record, ensure_ascii=False) + "\n")

    print(f"Wrote {len(MANUAL_PREDICTIONS)} records: {OUTPUT_PATH}")
    print()
    print("Note: this output was not freshly generated by calling a model API.")
    print("It is simply the existing manual judgment record re-written to a file.")
    print("To scale the sample up to n>=100, use normalize_slang.py to process")
    print("new rows through the API instead of continuing with this manual")
    print("record-keeping approach.")


if __name__ == "__main__":
    main()